begin;
set local search_path=public,extensions;
select no_plan();
create temporary table alerts(id uuid);
insert into alerts values(gen_random_uuid());
grant select on alerts to authenticated;
insert into public.notification(id,cooperative_id,kind,payload) select id,'10000000-0000-4000-8000-000000000001','critical_deviation','{}' from alerts;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select public.notification_read((select id from alerts))$$,'Producer can acknowledge an authorized broadcast');
select is((select count(*)::integer from public.notification_receipt where notification_id=(select id from alerts)),1,'Recipient sees their read status');
select lives_ok($$select public.notification_read((select id from alerts))$$,'Acknowledgment is idempotent');
select lives_ok($$select public.set_notification_preference('sms','+96170000000',true)$$,'Consent is saved by the actual recipient');
select throws_ok($$select public.prepare_notification_delivery((select id from alerts),'20000000-0000-4000-8000-000000000001')$$,'P0001','Alert delivery permission required','Producer cannot trigger privileged delivery');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::integer from public.notification_receipt where notification_id=(select id from alerts)),0,'Broadcast read status does not leak to another recipient');
select is((select count(*)::integer from public.notification_preference),0,'Recipient phone preferences are private');
select is(public.prepare_notification_delivery((select id from alerts),'20000000-0000-4000-8000-000000000001')->>'channel','sms','Supervisor delivery uses persisted consent');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select public.set_notification_preference('sms','+96170000000',false)$$,'Recipient can withdraw consent');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.prepare_notification_delivery((select id from alerts),'20000000-0000-4000-8000-000000000001')$$,'P0001','Saved recipient opt-in required','Withdrawal takes effect before delivery');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000009","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.notification_read((select id from alerts))$$,'P0001','Notification unavailable','Other cooperative cannot acknowledge the alert');
select throws_ok($$select public.prepare_notification_delivery((select id from alerts),'20000000-0000-4000-8000-000000000001')$$,'P0001','Critical alert unavailable','Other cooperative cannot prepare delivery');
select * from finish();
rollback;
